//! Built-in test scenes, all made of geometry generated by the C++ kernel. They exist to exercise and
//! verify the renderer; authored scenes replace them in later tracks.

use std::str::FromStr;

use bevy_asset::{Assets, RenderAssetUsages};
use bevy_camera::Camera3d;
use bevy_color::Color;
use bevy_ecs::resource::Resource;
use bevy_ecs::system::{Commands, Res, ResMut};
use bevy_math::{Mat4, Vec3};
use bevy_mesh::{Indices, Mesh, Mesh3d, PrimitiveTopology};
use bevy_transform::components::Transform;
use ve_kernel::{KernelError, Solid};
use ve_render::{VeAmbientLight, VeDirectionalLight, VeMaterial, VePointLight};
use ve_xr_web::{XrCamera, XrRig};

use crate::bench_scene::{BenchSpec, bench_scene as bench};
use crate::{interact, mock_hmd, status, wands};

/// Which built-in scene to show.
#[derive(Resource, Clone, Copy, Debug, Default, PartialEq, Eq)]
pub(crate) enum SceneKind {
    /// Editor comparison gallery with the legacy starter's dimensions and poses.
    Gallery,
    /// An empty lit room (floor, walls, sun, warm lights) for looking at authored models.
    Stage,
    /// A cube with a spherical bite, flat shaded, under a sun.
    #[default]
    Kernel,
    /// A grid of spheres sweeping roughness and metalness.
    Materials,
    /// A floor and spheres lit by three coloured point lights.
    Lights,
    /// The kernel scene seen through a mock headset: two eyes side by side.
    Stereo,
    /// A room-scale scene for a real or emulated headset: the cube at eye height, a floor, lights.
    Xr,
    /// A floor with a cube, a sphere and a pillar casting sun shadows onto it and each other.
    Shadows,
    /// Benchmark S1: a room with about 40 props (50k triangles).
    Bench1,
    /// Benchmark S2: a dense room, about 150 props (200k triangles).
    Bench2,
    /// Benchmark S3: a stress room, about 300 props (400k triangles).
    Bench3,
}

impl FromStr for SceneKind {
    type Err = ();

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        match s {
            "gallery" => Ok(Self::Gallery),
            "stage" => Ok(Self::Stage),
            "" | "kernel" => Ok(Self::Kernel),
            "materials" => Ok(Self::Materials),
            "lights" => Ok(Self::Lights),
            "stereo" => Ok(Self::Stereo),
            "xr" => Ok(Self::Xr),
            "shadows" => Ok(Self::Shadows),
            "bench1" => Ok(Self::Bench1),
            "bench2" => Ok(Self::Bench2),
            "bench3" => Ok(Self::Bench3),
            _ => Err(()),
        }
    }
}

/// Converts a kernel solid to a render mesh, with flat or smooth normals.
pub(crate) fn render_mesh(solid: &Solid, smooth: bool) -> Result<Mesh, KernelError> {
    let kernel_mesh = solid.to_mesh()?;
    let mut mesh = Mesh::new(
        PrimitiveTopology::TriangleList,
        RenderAssetUsages::default(),
    );
    mesh.insert_attribute(Mesh::ATTRIBUTE_POSITION, kernel_mesh.positions);
    mesh.insert_indices(Indices::U32(kernel_mesh.indices));
    if smooth {
        mesh.compute_normals();
    } else {
        // Flat shading shows sharp edges; it needs unshared vertices.
        mesh.duplicate_vertices();
        mesh.compute_flat_normals();
    }
    Ok(mesh)
}

fn sun(commands: &mut Commands, intensity: f32) {
    commands.spawn((
        VeDirectionalLight {
            color: Color::WHITE,
            intensity,
        },
        Transform::IDENTITY.looking_to(Vec3::new(-0.4, -0.8, -0.45), Vec3::Y),
    ));
}

fn camera(commands: &mut Commands, eye: Vec3, target: Vec3) {
    commands.spawn((
        Camera3d::default(),
        Transform::from_translation(eye).looking_at(target, Vec3::Y),
    ));
}

fn kernel_scene(commands: &mut Commands, meshes: &mut Assets<Mesh>) -> Result<(), KernelError> {
    spawn_bitten_cube(commands, meshes, Vec3::ZERO)?;
    sun(commands, 3.0);
    camera(commands, Vec3::new(1.6, 1.3, 2.0), Vec3::ZERO);
    Ok(())
}

/// Spawns the cube-minus-sphere that several scenes share, centred on `position`.
fn spawn_bitten_cube(
    commands: &mut Commands,
    meshes: &mut Assets<Mesh>,
    position: Vec3,
) -> Result<(), KernelError> {
    let solid = Solid::cube([1.0, 1.0, 1.0], true)?.difference(&Solid::sphere(0.65, 48)?)?;
    commands.spawn((
        Mesh3d(meshes.add(render_mesh(&solid, false)?)),
        VeMaterial {
            base_color: Color::srgb(0.60, 0.74, 0.92),
            roughness: 0.6,
            ..VeMaterial::default()
        },
        Transform::from_translation(position),
        interact::tag(&solid, "cube")?,
    ));
    Ok(())
}

/// The kernel scene viewed through the mock headset (two eyes side by side).
fn stereo_scene(commands: &mut Commands, meshes: &mut Assets<Mesh>) -> Result<(), KernelError> {
    spawn_bitten_cube(commands, meshes, Vec3::ZERO)?;
    sun(commands, 3.0);
    let head = mock_hmd::default_head(Vec3::new(0.4, 0.6, 2.2), Vec3::ZERO);
    mock_hmd::spawn_stereo_camera(commands, head);
    Ok(())
}

fn materials_scene(commands: &mut Commands, meshes: &mut Assets<Mesh>) -> Result<(), KernelError> {
    // One shared sphere mesh: every sphere below lands in a single instanced draw call.
    let sphere = meshes.add(render_mesh(&Solid::sphere(0.42, 64)?, true)?);
    for (row, metallic) in [0.0_f32, 1.0].into_iter().enumerate() {
        let base_color = if metallic > 0.5 {
            Color::srgb(1.0, 0.77, 0.34)
        } else {
            Color::srgb(0.80, 0.12, 0.10)
        };
        for column in 0..5_u8 {
            let roughness = f32::from(column) * 0.25;
            #[expect(clippy::cast_precision_loss, reason = "tiny grid indices")]
            let position = Vec3::new(
                (f32::from(column) - 2.0) * 1.0,
                0.55 - row as f32 * 1.1,
                0.0,
            );
            commands.spawn((
                Mesh3d(sphere.clone()),
                VeMaterial {
                    base_color,
                    metallic,
                    roughness,
                    ..VeMaterial::default()
                },
                Transform::from_translation(position),
            ));
        }
    }
    sun(commands, 3.0);
    commands.spawn((
        VePointLight {
            color: Color::srgb(0.7, 0.8, 1.0),
            intensity: 12.0,
            range: 12.0,
        },
        Transform::from_xyz(-3.0, 2.0, 3.0),
    ));
    camera(commands, Vec3::new(0.0, 0.0, 5.6), Vec3::ZERO);
    Ok(())
}

fn lights_scene(commands: &mut Commands, meshes: &mut Assets<Mesh>) -> Result<(), KernelError> {
    let floor = meshes.add(render_mesh(&Solid::cube([8.0, 0.1, 8.0], true)?, false)?);
    commands.spawn((
        Mesh3d(floor),
        VeMaterial {
            base_color: Color::srgb(0.75, 0.75, 0.78),
            roughness: 0.8,
            ..VeMaterial::default()
        },
        Transform::from_xyz(0.0, -0.55, 0.0),
    ));
    let ball = meshes.add(render_mesh(&Solid::sphere(0.5, 64)?, true)?);
    for (x, z) in [(-1.4_f32, 0.0_f32), (0.0, -0.6), (1.4, 0.2)] {
        commands.spawn((
            Mesh3d(ball.clone()),
            VeMaterial {
                base_color: Color::srgb(0.9, 0.9, 0.9),
                roughness: 0.35,
                ..VeMaterial::default()
            },
            Transform::from_xyz(x, 0.0, z),
        ));
    }
    for (color, position) in [
        (Color::srgb(1.0, 0.2, 0.2), Vec3::new(-2.0, 1.2, 1.5)),
        (Color::srgb(0.2, 1.0, 0.3), Vec3::new(0.0, 1.6, 1.2)),
        (Color::srgb(0.25, 0.4, 1.0), Vec3::new(2.0, 1.2, 1.5)),
    ] {
        commands.spawn((
            VePointLight {
                color,
                intensity: 14.0,
                range: 8.0,
            },
            Transform::from_translation(position),
        ));
    }
    camera(
        commands,
        Vec3::new(0.0, 1.8, 5.0),
        Vec3::new(0.0, -0.1, 0.0),
    );
    Ok(())
}

/// A room-scale scene for a headset. The tracking origin (the floor under the user) is placed 2.2 m
/// in front of a cube floating at eye height; before a session starts, a mono camera shows the same
/// view and `XrCamera` marks it as the one the headset takes over.
fn xr_scene(
    commands: &mut Commands,
    meshes: &mut Assets<Mesh>,
    rig: &mut XrRig,
) -> Result<(), KernelError> {
    rig.0 = Mat4::from_translation(Vec3::new(0.0, 0.0, 2.2));
    spawn_bitten_cube(commands, meshes, Vec3::new(0.0, 1.4, 0.0))?;
    let floor = meshes.add(render_mesh(&Solid::cube([6.0, 0.1, 6.0], true)?, false)?);
    commands.spawn((
        Mesh3d(floor),
        VeMaterial {
            base_color: Color::srgb(0.55, 0.57, 0.62),
            roughness: 0.9,
            ..VeMaterial::default()
        },
        Transform::from_xyz(0.0, -0.05, 0.0),
    ));
    wands::spawn_wands(commands, meshes)?;
    interact::spawn_lasers(commands, meshes)?;
    sun(commands, 2.5);
    for (color, position) in [
        (Color::srgb(1.0, 0.45, 0.25), Vec3::new(-1.2, 1.8, 0.8)),
        (Color::srgb(0.3, 0.55, 1.0), Vec3::new(1.2, 1.2, 0.8)),
    ] {
        commands.spawn((
            VePointLight {
                color,
                intensity: 9.0,
                range: 6.0,
            },
            Transform::from_translation(position),
        ));
    }
    commands.spawn((
        Camera3d::default(),
        XrCamera,
        Transform::from_xyz(0.0, 1.6, 2.2).looking_at(Vec3::new(0.0, 1.4, 0.0), Vec3::Y),
    ));
    Ok(())
}

/// Objects standing on a floor under the sun, so shadows land on the floor and on each other.
fn shadows_scene(commands: &mut Commands, meshes: &mut Assets<Mesh>) -> Result<(), KernelError> {
    let floor = meshes.add(render_mesh(&Solid::cube([10.0, 0.1, 10.0], true)?, false)?);
    let solids = [
        // Solid, smooth shading, label, colour, position of its centre.
        (
            Solid::cube([1.0, 1.0, 1.0], true)?,
            false,
            "box",
            Color::srgb(0.85, 0.45, 0.35),
            Vec3::new(0.6, 0.5, 0.4),
        ),
        (
            Solid::sphere(0.45, 48)?,
            true,
            "ball",
            Color::srgb(0.4, 0.7, 0.9),
            Vec3::new(-1.2, 0.45, 0.9),
        ),
        (
            Solid::cube([0.25, 1.8, 0.25], true)?,
            false,
            "pillar",
            Color::srgb(0.9, 0.85, 0.5),
            Vec3::new(-0.1, 0.9, -0.9),
        ),
    ];
    commands.spawn((
        Mesh3d(floor),
        VeMaterial {
            base_color: Color::srgb(0.7, 0.72, 0.75),
            roughness: 0.9,
            ..VeMaterial::default()
        },
        Transform::from_xyz(0.0, -0.05, 0.0),
    ));
    for (solid, smooth, label, base_color, position) in solids {
        commands.spawn((
            Mesh3d(meshes.add(render_mesh(&solid, smooth)?)),
            VeMaterial {
                base_color,
                roughness: 0.55,
                ..VeMaterial::default()
            },
            Transform::from_translation(position),
            interact::tag(&solid, label)?,
        ));
    }
    sun(commands, 3.0);
    camera(
        commands,
        Vec3::new(1.6, 2.4, 4.4),
        Vec3::new(-0.3, 0.3, 0.0),
    );
    Ok(())
}

/// Startup system: spawns the chosen test scene.
pub(crate) fn spawn_scene(
    mut commands: Commands,
    mut meshes: ResMut<Assets<Mesh>>,
    mut ambient: ResMut<VeAmbientLight>,
    mut rig: ResMut<XrRig>,
    choice: Res<SceneKind>,
) {
    ambient.intensity = 0.2;
    let built = match *choice {
        SceneKind::Gallery => crate::gallery::spawn(&mut commands, &mut meshes),
        SceneKind::Stage => {
            crate::bench_scene::stage_scene(&mut commands, &mut meshes, &mut ambient)
        }
        SceneKind::Kernel => kernel_scene(&mut commands, &mut meshes),
        SceneKind::Materials => materials_scene(&mut commands, &mut meshes),
        SceneKind::Lights => lights_scene(&mut commands, &mut meshes),
        SceneKind::Stereo => stereo_scene(&mut commands, &mut meshes),
        SceneKind::Xr => xr_scene(&mut commands, &mut meshes, &mut rig),
        SceneKind::Shadows => shadows_scene(&mut commands, &mut meshes),
        SceneKind::Bench1 => bench(
            &mut commands,
            &mut meshes,
            &mut ambient,
            &mut rig,
            BenchSpec::LIGHT,
        ),
        SceneKind::Bench2 => bench(
            &mut commands,
            &mut meshes,
            &mut ambient,
            &mut rig,
            BenchSpec::DENSE,
        ),
        SceneKind::Bench3 => bench(
            &mut commands,
            &mut meshes,
            &mut ambient,
            &mut rig,
            BenchSpec::STRESS,
        ),
    };
    if let Err(error) = built {
        status::report_error(format!("scene {:?} failed: {error}", *choice));
    }
}
